const projectPattern = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
const baseURL = () => (process.env.AGENT_SYSTEM_BFF_BASE_URL || "http://agent-system-backend:8000").replace(/\/+$/, "");
function record(value) { return Boolean(value) && typeof value === "object" && !Array.isArray(value); }
function sourceOf(value) {
  if (!record(value) || typeof value.type !== "string") throw new Error("Plugin source must be an object with type");
  if (!["local", "npm", "git"].includes(value.type)) throw new Error("Plugin source type is unsupported");
  const allowed = value.type === "local" ? ["type", "path"] : value.type === "npm" ? ["type", "package"] : ["type", "repository", "revision"];
  if (Object.keys(value).some((key) => !allowed.includes(key)) || allowed.slice(1).some((key) => typeof value[key] !== "string" || !value[key].trim())) throw new Error("Plugin source fields are invalid");
  return Object.fromEntries(allowed.map((key) => [key, value[key].trim()]));
}

export default {
  description: "匯入已授權的 OpenCode Plugin，回傳兩個 runtime 的能力名稱供 Agent 辨識登錄。",
  input: {"type":"object","properties":{"source":{"type":"string","minLength":2,"maxLength":20000,"description":"JSON object for the user-approved local, npm, or git source"}},"required":["source"],"additionalProperties":false},
  async execute(args, context) {
    const directory = typeof context?.directory === "string" ? context.directory.replace(/\\/g, "/") : "";
    const match = directory.match(/\/(?:workflow\/)?projects\/([^/]+)\/?$/);
    const project = match?.[1];
    if (!project || !projectPattern.test(project) || typeof context?.sessionID !== "string" || !context.sessionID) throw new Error("Canonical session Project context is unavailable");
    const source = sourceOf(JSON.parse(args.source));
    const endpoint = new URL("/bff/projects/" + encodeURIComponent(project) + "/plugins/import", baseURL());
    const response = await fetch(endpoint, { method: "POST", headers: { "content-type": "application/json", "x-agent-system-workspace": project }, body: JSON.stringify({ source }), signal: AbortSignal.timeout(180000) });
    const payload = await response.json().catch(() => undefined);
    if (!response.ok || !record(payload)) throw new Error("Plugin Import failed with a bounded public error");
    const targets = record(payload.targets) ? {
      main: record(payload.targets.main) ? { status: payload.targets.main.status, runtimeStatus: payload.targets.main.runtimeStatus } : undefined,
      "workflow-test": record(payload.targets["workflow-test"]) ? { status: payload.targets["workflow-test"].status, runtimeStatus: payload.targets["workflow-test"].runtimeStatus } : undefined,
    } : undefined;
    const names = (value) => Array.isArray(value) ? value.filter((name) => typeof name === "string" && name.length <= 200).slice(0, 200) : [];
    const runtimeEvidence = Object.fromEntries(["main", "workflow-test"].map((target) => {
      const evidence = payload.runtimeEvidence?.[target];
      return [target, record(evidence) && !evidence.unavailable ? { agents: names(evidence.agents), tools: names(evidence.tools), skills: names(evidence.skills), mcp: names(evidence.mcp) } : { unavailable: "Plugin runtime inventory is unavailable" }];
    }));
    return { content: JSON.stringify({
      project,
      pluginName: typeof payload.pluginName === "string" ? payload.pluginName : undefined,
      source: record(payload.source) ? payload.source : undefined,
      resolved: record(payload.resolved) ? {
        contentHash: typeof payload.resolved.contentHash === "string" ? payload.resolved.contentHash : undefined,
        version: typeof payload.resolved.version === "string" ? payload.resolved.version : undefined,
        revision: typeof payload.resolved.revision === "string" ? payload.resolved.revision : undefined,
      } : undefined,
      targets, runtimeEvidence,
      warnings: Array.isArray(payload.warnings) ? payload.warnings.slice(0, 8) : [],
    }), metadata: { title: "Plugin Import status" } };
  },
};

const projectPattern = /^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/;
const targets = new Set(["main", "workflow-test"]);
const kinds = new Set(["agent", "command", "tool", "skill", "mcp"]);
const provenanceKinds = new Set(["npm", "git", "local"]);
const statuses = new Set(["verified", "stale", "runtime-unavailable", "unverified", "missing"]);
const baseURL = () => (process.env.AGENT_SYSTEM_BFF_BASE_URL || "http://agent-system-backend:8000").replace(/\/+$/, "");
const record = (value) => Boolean(value) && typeof value === "object" && !Array.isArray(value);
const text = (value, max, required = false) => { if (typeof value !== "string" || value.length > max || (required && !value.trim())) throw new Error("Plugin registration field is invalid"); return value; };
function registrationOf(value, project) {
  if (!record(value) || value.scope !== "project" || value.project !== project || !targets.has(value.target)) throw new Error("Plugin registration scope or target is invalid");
  if (!record(value.provenance) || !provenanceKinds.has(value.provenance.kind)) throw new Error("Plugin provenance is invalid");
  if (!record(value.recognition) || !["partial", "complete"].includes(value.recognition.status)) throw new Error("Plugin recognition is invalid");
  if (!Array.isArray(value.contributions) || value.contributions.length > 200) throw new Error("Plugin contributions are invalid");
  const contributions = value.contributions.map((item) => {
    if (!record(item) || !kinds.has(item.kind) || !text(item.name, 200, true) || (item.status !== undefined && item.status !== "unverified")) throw new Error("Plugin contribution is invalid");
    return { kind: item.kind, name: item.name, ...(Array.isArray(item.toolNames) ? { toolNames: item.toolNames.slice(0, 200).map((name) => text(name, 200, true)) } : {}), ...(item.description !== undefined ? { description: text(item.description, 2000) } : {}), status: "unverified", ...(item.evidence !== undefined ? { evidence: text(item.evidence, 2000) } : {}) };
  });
  return { scope: "project", project, target: value.target, pluginName: text(value.pluginName, 101, true), ...(value.description !== undefined ? { description: text(value.description, 2000, true) } : {}), ...(value.package !== undefined ? { package: text(value.package, 214, true) } : {}), provenance: { kind: value.provenance.kind, source: text(value.provenance.source, 500, true), revision: text(value.provenance.revision, 200, true) }, recognition: { status: value.recognition.status, unavailable: Array.isArray(value.recognition.unavailable) ? value.recognition.unavailable.slice(0, 100).map((item) => text(item, 500)) : [] }, backgroundBehaviors: Array.isArray(value.backgroundBehaviors) ? value.backgroundBehaviors.slice(0, 50).map((item) => ({ kind: "hook", name: text(item.name, 200, true), description: text(item.description, 500, true) })) : [], contributions };
}
export default { description: "Register an authorized imported Plugin and read its project Catalog readiness.", input: {"type":"object","properties":{"registration":{"type":"string","minLength":2,"maxLength":600000}},"required":["registration"],"additionalProperties":false}, async execute(args, context) {
  const token = process.env.AGENT_SYSTEM_PLUGIN_REGISTRATION_TOKEN;
  const directory = typeof context?.directory === "string" ? context.directory.replace(/\\/g, "/") : "";
  const project = directory.match(/\/(?:workflow\/)?projects\/([^/]+)\/?$/)?.[1];
  if (!token || !project || !projectPattern.test(project) || typeof context?.sessionID !== "string" || !context.sessionID) throw new Error("Canonical session Project context or registration credential is unavailable");
  const input = registrationOf(JSON.parse(args.registration), project);
  const registrationEndpoint = new URL("/bff/opencode-plugin-contributions/register", baseURL());
  const registrationResponse = await fetch(registrationEndpoint, { method: "POST", headers: { "content-type": "application/json", authorization: "Bearer " + token, "x-agent-system-workspace": project }, body: JSON.stringify(input), signal: AbortSignal.timeout(30000) });
  const registrationPayload = await registrationResponse.json().catch(() => undefined);
  if (!registrationResponse.ok || !record(registrationPayload)) throw new Error("Plugin Contribution Catalog registration failed");
  const catalogEndpoint = new URL("/bff/workflow-resources", baseURL());
  catalogEndpoint.searchParams.set("project", project);
  catalogEndpoint.searchParams.set("includeGlobal", "false");
  const catalogResponse = await fetch(catalogEndpoint, { headers: { "x-agent-system-workspace": project }, signal: AbortSignal.timeout(30000) });
  const catalogPayload = await catalogResponse.json().catch(() => undefined);
  if (!catalogResponse.ok || !record(catalogPayload) || !Array.isArray(catalogPayload.pluginContributions)) throw new Error("Plugin Contribution Catalog read failed");
  const entry = catalogPayload.pluginContributions.find((item) => record(item) && item.pluginName === input.pluginName && item.scope === "project");
  if (!entry) throw new Error("Imported Plugin is missing from the project Catalog");
  const targetStatuses = { main: statuses.has(entry.targetStatuses?.main) ? entry.targetStatuses.main : "missing", "workflow-test": statuses.has(entry.targetStatuses?.["workflow-test"]) ? entry.targetStatuses["workflow-test"] : "missing" };
  const status = statuses.has(entry.status) ? entry.status : "unverified";
  const groups = ["agents", "tools", "skills", "mcp"];
  const contributions = groups.flatMap((group) => Array.isArray(entry.contributions?.[group]) ? entry.contributions[group].slice(0, 50).map((item) => record(item) ? { name: typeof item.name === "string" ? item.name.slice(0, 200) : "", availability: typeof item.availability === "string" ? item.availability.slice(0, 64) : "unknown" } : undefined) : []).filter(Boolean).slice(0, 200);
  return { content: JSON.stringify({ pluginName: input.pluginName, scope: "project", project, status, targetStatuses, contributions: contributions.slice(0, 200) }), metadata: { title: "Plugin Contribution Catalog status" } };
} };

export default {
  description: "依作者文件登錄參數定義，保留既有值，不啟動環境；回傳待補填名稱。",
  input: {"type":"object","properties":{"pluginName":{"type":"string","pattern":"^[A-Za-z0-9][A-Za-z0-9_.-]{0,99}$"},"requirements":{"type":"string","minLength":2,"maxLength":20000}},"required":["pluginName","requirements"],"additionalProperties":false},
  async execute(args, context) {
    const directory = typeof context?.directory === "string" ? context.directory.replace(/\\/g, "/") : "";
    const project = directory.match(/\/(?:workflow\/)?projects\/([^/]+)\/?$/)?.[1];
    if (!project || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(project) || !context?.sessionID) throw new Error("Canonical session Project context is unavailable");
    const parameters = JSON.parse(args.requirements);
    if (!Array.isArray(parameters) || parameters.length > 100 || parameters.some(item => !item || typeof item !== "object" || "value" in item)) throw new Error("Only parameter definitions are accepted");
    const endpoint = new URL("/bff/projects/" + encodeURIComponent(project) + "/plugins/" + encodeURIComponent(args.pluginName) + "/environment-parameter-definitions", process.env.AGENT_SYSTEM_BFF_BASE_URL || "http://agent-system-backend:8000");
    const response = await fetch(endpoint, { method: "POST", headers: { "content-type": "application/json", "x-agent-system-workspace": project }, body: JSON.stringify({ parameters }), signal: AbortSignal.timeout(30000) });
    const payload = await response.json().catch(() => undefined);
    if (!response.ok || !Array.isArray(payload?.parameters) || !Array.isArray(payload?.missingRequired)) throw new Error("Plugin parameter definitions could not be recorded");
    return { content: JSON.stringify({ project, pluginName: args.pluginName, target: "main", parameters: payload.parameters, missingRequired: payload.missingRequired }), metadata: { title: "Plugin 參數定義與待補填項目" } };
  },
};
